const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2017 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.breakpoint-list {\n  padding-bottom: 3px;\n}\n\n.breakpoint-list .dom-breakpoint > div {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.breakpoint-entry {\n  display: flex;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  overflow: hidden;\n  padding: 2px 0;\n}\n\n.breakpoint-entry:focus-visible {\n  background-color: var(--legacy-focus-bg-color);\n}\n\n.breakpoint-list .breakpoint-entry:hover {\n  background-color: var(--color-background-elevation-2);\n}\n\n.breakpoint-hit {\n  background-color: var(--color-background-elevation-2);\n  border-right: 3px solid var(--color-details-hairline);\n  color: var(--color-text-primary);\n}\n\n@media (forced-colors: active) {\n  .breakpoint-entry:focus-visible,\n  .breakpoint-list .breakpoint-entry:hover {\n    forced-color-adjust: none;\n    background-color: Highlight;\n  }\n\n  .breakpoint-entry:focus-visible *,\n  .breakpoint-list .breakpoint-entry:hover * {\n    color: HighlightText;\n  }\n}\n\n/*# sourceURL=domBreakpointsSidebarPane.css */\n");export default styles;